// ============================================
// Generate Secure Validation Token
// ============================================

const data = $input.first().json;

// Debug logging (optional - can be removed in production)
console.log('🔍 Input data:', JSON.stringify(data, null, 2));

// Extract required fields
const timesheetId = data.timesheet_id;
const clientEmail = data.client_email;

console.log('📋 Timesheet ID:', timesheetId);
console.log('📧 Client Email:', clientEmail);

// ============================================
// Generate Unique Token
// Uses timestamp + random strings for uniqueness
// ============================================

const timestamp = Date.now().toString(36);
const randomPart1 = Math.random().toString(36).substring(2, 15);
const randomPart2 = Math.random().toString(36).substring(2, 15);
const token = `${timestamp}-${randomPart1}-${randomPart2}`;

console.log('✅ Token generated:', token);

// ============================================
// Create Validation URL
// Customize this URL to match your app domain
// ============================================

const appUrl = data.app_url || 'http://localhost:3000';  // ← Change to your domain
const validationUrl = `${appUrl}/validation/${token}`;

// ============================================
// Set Token Expiration
// Default: 7 days from now
// Adjust the number below to change expiration
// ============================================

const expiresAt = new Date();
expiresAt.setDate(expiresAt.getDate() + 7);  // ← Change 7 to your desired days

// ============================================
// Return Formatted Data
// ============================================

return {
  json: {
    ...data,
    token: token,
    client_email: clientEmail,
    expires_at: expiresAt.toISOString(),
    used: false,
    validation_url: validationUrl,

    // Additional metadata (optional)
    token_created_at: new Date().toISOString(),
    token_expires_in_days: 7
  }
};

